/*
 * A391981  Irregular triangle read by rows where row n lists the trimmed
 *          zero-based partial alternating sums of the prime indices of n.
 * https://oeis.org/A391981
 *
 * Offset:    2    (a(2) is the first term)
 * Keywords:  nonn, tabf, changed
 * Formula:   a(n) = the nth entry in the flattened triangle formed by the
 *            trimmed zero‑based partial alternating sums of the prime indices
 *            of n. The triangle rows are generated by taking the prime index
 *            multiset of n, computing its a_0–partial alternating sums (k=0),
 *            trimming the leading zero and then flatten...
 * Range:     u8 n <= 4780, u16 n <= 9324, u32 n <= 9324, u64 n <= 9324,
 *            u128 n <= 9324, big any n
 * Helpers:   build_primes_upto, factor_u64
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>

#include "../utils/factor_u64.h"
#include "../utils/build_primes_upto.h"

/* Cache of already generated terms (flattened triangle), indexed
   from 0 corresponding to a(2). */
static seq_t *cache      = NULL;
static size_t cache_cap  = 0;
static size_t cache_size = 0;       /* number of terms currently stored */

/* Next row to be generated. */
static idx_t next_row = 2;

/* List of primes up to prime_limit, 1‑based indices.  prime_cnt == prime_limit – 1. */
static uint64_t *prime_list = NULL;
static size_t   prime_cnt   = 0;
static idx_t    prime_limit = 0;

/* Ensure that prime_list contains all primes ≤ limit (1‑based indices). */
static void ensure_primes(idx_t limit)
{
    if (limit <= prime_limit)
        return;
    if (prime_list)
        free(prime_list);
    build_primes_upto(limit, &prime_list, &prime_cnt);
    prime_limit = limit;
}

/* Return the 1‑based index of prime p (p is guaranteed to be prime). */
static idx_t prime_index(uint64_t p)
{
    size_t lo = 0, hi = prime_cnt;
    while (lo < hi) {
        size_t mid = (lo + hi) >> 1;
        if (prime_list[mid] < p)
            lo = mid + 1;
        else
            hi = mid;
    }
    return (idx_t)(lo + 1);   /* primes are 1‑based */
}

/* Grow the cache array to hold at least 'need' elements. */
static void grow_cache(size_t need)
{
    if (cache_cap >= need)
        return;
    size_t new_cap = cache_cap ? cache_cap * 2 : 64;
    while (new_cap < need)
        new_cap <<= 1;
    cache = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
    cache_cap = new_cap;
}

/* Main sequence function. */
seq_t a(idx_t n)
{
    if (n < 2)
        return 0;              /* below offset – undefined, return 0 */

    size_t target = (size_t)(n - 2);   /* index into cache */

    /* Return already computed value. */
    if (target < cache_size)
        return cache[target];

    /* Extend cache until we have enough terms. */
    while (cache_size <= target) {
        idx_t row = next_row++;

        /* Ensure all primes up to current row are available for factorisation. */
        ensure_primes(row);

        /* Factorise 'row'. */
        uint64_t primes[128];
        uint64_t exps[128];
        size_t nf = 0;
        factor_u64((uint64_t)row, primes, exps, &nf);

        /* Compute total number of indices (total exponents). */
        idx_t m = 0;
        for (size_t i = 0; i < nf; ++i)
            m += exps[i];

        /* Reserve space for the new row. */
        grow_cache(cache_size + m);

        /* Generate the trimmed partial alternating sums for this row. */
        int64_t t = 0;        /* alternating sum of q with sign (-1)^i */
        idx_t j  = 1;         /* 1‑based position within this row */

        for (size_t i = 0; i < nf; ++i) {
            idx_t idxp = prime_index(primes[i]);

            for (uint64_t k = 0; k < exps[i]; ++k) {
                /* Update alternating sum t. */
                if (j & 1)       /* odd position: subtract */
                    t -= (int64_t)idxp;
                else             /* even: add */
                    t += (int64_t)idxp;

                /* Compute s_j = (-1)^j * t.  For odd j, -t; for even j, t. */
                seq_t val = (j & 1) ? (seq_t)(-t) : (seq_t)t;

                cache[cache_size++] = val;
                ++j;
            }
        }
    }

    return cache[target];
}
